function click_web()
{
    // 定义要点击的元素选择器
    const clickText = [
        { type: 'linkText', text: 'Accept & Close' },
        { type: 'xpath', text: '//xpl-full-text-toc//span' },
        { type: 'className', text: 'document-abstract-toggle-btn' },
        { type: 'linkText', text: ' (Show More) ' }
    ];

    // 辅助函数：根据文本内容获取元素
    function getElementsByText(text) {
        const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null, false);
        const elements = [];
        let node;

        while (node = walker.nextNode()) {
            if (node.nodeValue.includes(text)) {
                elements.push(node.parentNode);
            }
        }

        return elements;
    }

    // 遍历并点击元素
    clickText.forEach(item => {
        let elements;
        try {
            switch (item.type) {
                case 'linkText':
                    elements = getElementsByText(item.text).filter(element => element.tagName.toLowerCase() === 'a');
                    break;
                case 'xpath':
                    elements = document.evaluate(item.text, document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
                    break;
                case 'className':
                    elements = document.getElementsByClassName(item.text);
                    break;
                default:
                    console.log(`Unsupported selector type: ${item.type}`);
                    return;
            }

            if (elements) {
                if (item.type === 'xpath') {
                    for (let i = 0; i < elements.snapshotLength; i++) {
                        try {
                            elements.snapshotItem(i).click();
                        } catch (error) {
                            console.error(`Failed to click element: ${error.message}`);
                        }
                    }
                } else {
                    for (let element of elements) {
                        try {
                            element.click();
                        } catch (error) {
                            console.error(`Failed to click element: ${error.message}`);
                        }
                    }
                }
            }
        } catch (error) {
            console.error(`Failed to find elements: ${error.message}`);
        }
    });
}
click_web();

function replaceElementsWithText(selectors) {
    selectors.forEach(selector  => {
        const elements = document.querySelectorAll(selector); 
        elements.forEach(element  => {
            // 克隆元素以避免修改原始DOM 
            const clone = element.cloneNode(true); 

            // 移除所有script标签 
            const scripts = clone.querySelectorAll('script'); 
            scripts.forEach(script  => script.remove()); 

            // 创建新的文本节点替换原元素 
            const textNode = document.createTextNode(clone.textContent); 
            element.parentNode.replaceChild(textNode,  element);
        });
    });
}

