// ★ 公式转图片-第一步：在抓取outerHTML之前，把每个disp-formula/inline-formula元素的原始LaTeX
// 源码用 MathJax.Hub.getAllJax() 找回来，写入 data-original-tex 属性。
// 原因：MathJax v2渲染完成后会删除原始的 <script type="math/tex">，
// 尤其是inline公式的源码在DOM里完全消失，只能通过MathJax内部保存的 originalText 找回。
// disp-formula(块级公式)虽然会在旁边生成 <span class="tex tex2jax_ignore"> 备份，
// 但inline-formula(行内公式)没有这个备份，所以必须统一用MathJax.Hub API处理两种情况。
function stampOriginalTex() {
    try {
        if (typeof MathJax === 'undefined' || !MathJax.Hub || !MathJax.Hub.getAllJax) {
            return 0;
        }
        var allJax = MathJax.Hub.getAllJax();
        var stamped = 0;
        for (var i = 0; i < allJax.length; i++) {
            var jax = allJax[i];
            var script = jax.SourceElement ? jax.SourceElement() : null;
            if (!script) continue;
            var formulaEl = script.closest ? script.closest('disp-formula, inline-formula') : null;
            if (formulaEl) {
                formulaEl.setAttribute('data-original-tex', jax.originalText);
                stamped++;
            }
        }
        return stamped;
    } catch (e) {
        console.error('stampOriginalTex failed: ' + e.message);
        return 0;
    }
}
